local api = require(script.apis.Neza)

local module = {}

function module:InitFolder(folder)
    return api:_init(folder)
end

function module:Start(folder, callback)
    return api:_start(folder, callback)
end

function module:GetModel(modelName, vmName)
    return api:_getModel(modelName, vmName)
end

function module:GetViewModel(vmName)
    return api:_getViewModel(vmName)
end

function module:StartDebugger()
    return api:_enableStudioDebugger()
end

function module:Boot(cfg)
    return api:_boot(cfg)
end

function module:Instance(t: "View" | "ViewModel", ...)
    return api:_instance(t)
end

return module